cd /bench/home/work; python3 - <<'EOF'
import os,re,subprocess,collections
decls=[]
for root,dirs,files in os.walk('internal'):
    for f in files:
        if not f.endswith('.go') or f.endswith('_test.go'): continue
        p=os.path.join(root,f)
        src=open(p).read()
        pkg=re.search(r'^package (\w+)',src,re.M).group(1)
        for m in re.finditer(r'^func (\([^)]*\) )?([A-Za-z]\w*)\(',src,re.M):
            decls.append((pkg,m.group(2),p,bool(m.group(1))))
files=[f for f in subprocess.run(['bash','-c',"find . -name '*.go' -not -path './proto/gen/*' -not -name '*_test.go'"],capture_output=True,text=True).stdout.split()]
texts={f:open(f).read() for f in files}
res=collections.Counter(); det=collections.defaultdict(list)
for pkg,name,p,ismeth in decls:
    if ismeth:
        pat=re.compile(r'\.'+name+r'\s*\(')
    else:
        pat=re.compile(r'\b'+pkg+r'\.'+name+r'\s*\(')
    tot=0
    for f,t in texts.items():
        n=len(pat.findall(t))
        # subtract declaration occurrences in own file? decl doesn't match patterns above (func X( has no dot/pkg)
        if n: tot+=n; det[(pkg,name,p,ismeth)].append((f,n))
    res[(pkg,name,p,ismeth)]=tot
for k,v in res.most_common(20):
    print(v,k[0]+"."+k[1], k[2], "method" if k[3] else "func")
EOF

